 Copy-Fixture 'with-exif.jpg' (Join-Path $inputDir 'تصوير.jpg')
} "3`n" {Assert ($r.Code -eq 0) $r.Text;$row=Import-Csv -LiteralPath (Join-Path $output 'organized-dates\dates.csv');Assert ($row.DateSource -like 'EXIF*' -and $row.Copy.StartsWith('2020\05\')) 'Shooting date ignored.'}
