 Case 'Scanner crossed corners refused' 'Document Scanner' {Copy-Fixture 'paper.png' (Join-Path $inputDir 'paper.png')} "3`n1`n1`n120,80 620,730 650,140 80,650`n" {Assert ($r.Code -ne 0 -and -not @(Get-SafeFiles $output $null -Recurse).Count) 'Crossed corners accepted.'}
 Case 'Scanner per-file corner batch' 'Document Scanner' {Ensure-Directory (Join-Path $inputDir 'Corners');foreach($name in @('أول.png','ثاني.png')){Copy-Fixture 'paper.png' (Join-Path $inputDir $name);[IO.File]::WriteAllText((Join-Path $inputDir ('Corners\'+$name+'.txt')),'120,80 650,140 620,730 80,650')}} "3`n1`n1`n" {Assert ($r.Code -eq 0) $r.Text;Assert (@(Get-SafeFiles $output @('.png') -Recurse|Where-Object Name -eq scanned.png).Count -eq 2) 'Batch corner files not applied.'}
 Case 'PDF OCR retains existing text and white page' 'PDF OCR' {[void](Invoke-Checked $qpdf @('--empty','--pages','scans.pdf','1','pages.pdf','1','blank.pdf','1','scans.pdf','2','--','mixed.pdf'));Copy-Fixture 'mixed.pdf' (Join-Path $inputDir 'mixed.pdf')} "1`n1`n2`n" {Assert ($r.Code -eq 0) $r.Text;$pdf=Join-Path $output 'mixed.pdf.ocr\searchable.pdf';Assert ((PDF-Count $pdf) -eq 4) 'Mixed OCR lost pages.';$rows=@(Import-Csv -LiteralPath (Join-Path $output 'mixed.pdf.ocr\pages.csv'));Assert ($rows[1].Status -like 'Existing*' -and $rows[2].Status -like 'White page*') 'Existing text or white page not handled.';$text=Get-PDFText 'checked.pdf' 2;Assert ([regex]::Matches($text,'test PAGE ONE').Count -eq 1) 'Existing text duplicated.';$arabic=Get-PDFText 'checked.pdf' 4;Assert ($arabic.Contains('مرحبا')) 'Mixed Arabic PDF not searchable.';[IO.File]::Copy($pdf,(Join-Path $fixtures 'searchable-fixture.pdf'),$true)}
 Case 'PDF Search finds real Arabic OCR layer' 'PDF Search' {Copy-Fixture 'searchable-fixture.pdf' (Join-Path $inputDir 'ممسوح.pdf')} "2`nمرحبا`n" {Assert ($r.Code -eq 0) $r.Text;$rows=@(Import-Csv -LiteralPath (Join-Path $output 'search-report\matches.csv'));Assert ($rows.Count -eq 1 -and $rows[0].Page -eq '4') 'Arabic OCR search did not locate actual page.'}
 Case 'PDF OCR rejects encrypted input' 'PDF OCR' {Copy-Fixture 'unicode-protected.pdf' (Join-Path $inputDir 'a.pdf')} "1`n1`n1`n" {Assert ($r.Code -ne 0 -and -not @(Get-SafeFiles $output $null -Recurse).Count) 'Encrypted PDF processed silently.'}
 Case 'Batch PDF OCR two scanned documents' 'PDF OCR' {foreach($name in @('أول.pdf','ثاني.pdf')){Copy-Fixture 'scans.pdf' (Join-Path $inputDir $name)}} "1`n1`n1`n" {Assert ($r.Code -eq 0) $r.Text;$files=@(Get-SafeFiles $output @('.pdf') -Recurse);Assert ($files.Count -eq 2) 'OCR batch missing document.';foreach($f in $files){Assert ((PDF-Count $f.FullName) -eq 2) 'OCR batch page count.';Assert ((Get-PDFText 'checked.pdf' 1).Contains('TOOLS BAT OCR TEST') -and (Get-PDFText 'checked.pdf' 2).Contains('مرحبا')) 'OCR batch searchable content wrong.'}}
}
$results.ToArray()|ConvertTo-Json -Depth 5|Set-Content -LiteralPath (Join-Path $PSScriptRoot ('hundred-options'+$(if($Only){'-focused'})+'-results.json')) -Encoding UTF8
if(@($results|Where-Object{-not $_.Passed}).Count){exit 1};exit 0
